window.GKA.contentParts.push({ subject: "reading", grade: "g4", levels: [
  {"n":1,"name":"Multisyllable words","skill":"Break long words into parts","speed":1,"words":[["adventure","We went on an adventure."],["important","This is important."],["remember","Remember your lines."],["beautiful","A beautiful sunset."],["favorite","My favorite book."],["different","A different color."],["tomorrow","See you tomorrow."],["together","We sing together."],["interesting","An interesting fact."],["community","Our community helps."],["celebration","A celebration with cake and music."],["impossible","Nothing is impossible if you practice."],["temperature","The temperature dropped overnight."],["vegetable","A carrot is a vegetable."],["electricity","Electricity powers the lights."],["information","Look up the information online."],["dictionary","Check the dictionary for the meaning."],["experiment","We did an experiment with magnets."],["neighborhood","Our neighborhood has a park."],["responsible","A responsible student finishes homework."]],"story":{"title":"The Community Garden","text":"Last spring, our community decided to turn an empty lot into a garden. At first it seemed like an impossible job. The ground was hard, and there was trash everywhere. But every Saturday, different families came to help. Some dug, some planted, and some brought lemonade. By summer the lot was beautiful. Tomatoes climbed the fence and sunflowers nodded over the path. My favorite part was not the vegetables. It was remembering how many neighbors I had never met before, and how we built something interesting together.","questions":[{"q":"What did the community build?","o":["A garden in an empty lot","A playground","A library"],"a":0},{"q":"Why did the job seem impossible at first?","o":["The ground was hard and full of trash","Nobody had seeds","It rained every day"],"a":0},{"q":"What was the narrator's favorite part?","o":["Meeting neighbors","The tomatoes","The lemonade"],"a":0},{"q":"What does the story show about working together?","o":["Many people can do what one person cannot","Gardens are easy","Saturdays are boring"],"a":0}]},"story2":{"title":"The Neighborhood Library Box","text":"Miguel noticed that the small library box on his street was always empty. Nobody remembered to refill it. He thought it was impossible to keep it stocked alone, so he made it a neighborhood project. Every family added one book. He added a notebook for comments. Within a month, the box was overflowing, and the notebook was full of recommendations. Being responsible, he discovered, works best when it is shared.","questions":[{"q":"What problem did Miguel notice?","o":["The library box was always empty","The park was closed","The street was dark"],"a":0},{"q":"How did he solve it?","o":["Every family added one book","He bought books","He closed the box"],"a":0},{"q":"What did he add to the box?","o":["A notebook for comments","A lock","A lamp"],"a":0},{"q":"What did Miguel learn?","o":["Responsibility works best when shared","Books are heavy","Boxes break"],"a":0}]}},
  {"n":3,"name":"Prefixes dis-, mis-, pre-","skill":"Not, wrongly, before","speed":1,"words":[["disagree","We disagree politely."],["disappear","The fog will disappear."],["dishonest","A dishonest answer."],["misplace","Do not misplace the key."],["misunderstand","I misunderstand sometimes."],["mistake","A small mistake."],["preview","A movie preview."],["prepare","Prepare for the test."],["prehistoric","Prehistoric animals."],["preheat","Preheat the oven."],["disconnect","Disconnect the cable first."],["dislike","I dislike cold soup."],["disobey","The puppy would disobey every rule."],["misbehave","Do not misbehave in class."],["misspell","It is easy to misspell that word."],["mislead","The sign could mislead drivers."],["precaution","Take the precaution of wearing a helmet."],["predict","Predict what happens next."],["preschool","My sister is in preschool."],["preorder","You can preorder the game."]],"story":{"title":"The Misplaced Map","text":"Before the hike, Dad told us to prepare carefully. I packed water, snacks, and the trail map. Halfway up the mountain, the map had disappeared. Had I misplaced it? My sister and I began to disagree about which path to take. Then I remembered the preview sign at the start of the trail: blue markers lead to the waterfall. We followed the blue paint on the trees. It was a mistake to lose the map, but it was not a mistake to pay attention. The waterfall was prehistoric-looking, with ferns taller than me.","questions":[{"q":"What did the narrator lose?","o":["The trail map","The water","The snacks"],"a":0},{"q":"How did they find the waterfall?","o":["They followed blue markers","They asked a ranger","They used a phone"],"a":0},{"q":"What does 'prehistoric-looking' tell you about the waterfall?","o":["It looked very old and wild","It was built recently","It was small"],"a":0},{"q":"What lesson did the narrator learn?","o":["Paying attention matters","Maps are useless","Never hike with a sister"],"a":0}]},"story2":{"title":"The Misunderstood Message","text":"Dana's note said, meet at the big tree, do not be late. Her friends disagreed about which tree was big. Half went to the oak, half to the pine. Everyone was on time and everyone was in the wrong place. The next day Dana prepared a better note: the oak by the gate, with a drawing. Nobody misunderstood, and nobody disappeared.","questions":[{"q":"Why did the friends go to different trees?","o":["They disagreed about which tree was big","They were late","They forgot"],"a":0},{"q":"Was anyone late?","o":["No","Yes, everyone","Only Dana"],"a":0},{"q":"How did Dana fix the note?","o":["She named the tree and added a drawing","She used a megaphone","She cancelled"],"a":0},{"q":"Which prefix means wrong?","o":["mis-","pre-","re-"],"a":0}]}},
  {"n":6,"name":"Suffixes -tion, -ment, -ness","skill":"Turn actions into things","speed":1,"words":[["invention","A clever invention."],["attention","Pay attention."],["education","Education matters."],["movement","A sudden movement."],["agreement","We reached an agreement."],["excitement","Full of excitement."],["kindness","Show kindness."],["darkness","Total darkness."],["happiness","Happiness is a choice."],["weakness","Everyone has a weakness."],["celebration","The celebration lasted all night."],["direction","Which direction is north?"],["population","The town's population grew."],["government","The government makes laws."],["treatment","The nurse gave treatment."],["equipment","Pack the camping equipment."],["sadness","He felt sadness at goodbye."],["fairness","Fairness means equal rules."],["illness","Rest helps an illness."],["brightness","Turn down the brightness."]],"story":{"title":"Lights Out","text":"During the storm, the power went out and the house fell into darkness. My little brother's excitement turned to fear. I remembered a lesson from school about attention: when you cannot see, your other senses sharpen. We sat still and listened. Rain on the roof. The movement of the cat on the stairs. Then Mom lit a candle, and we made an agreement to tell one story each. By the time the lights returned, my brother's happiness was back. Kindness, I learned, can be as simple as a candle and a story.","questions":[{"q":"What caused the darkness?","o":["The storm knocked out the power","Someone turned off the lights","It was night"],"a":0},{"q":"What did they agree to do?","o":["Tell one story each","Go to sleep","Call a neighbor"],"a":0},{"q":"What happens to your senses in the dark, according to the story?","o":["They sharpen","They stop working","Nothing changes"],"a":0},{"q":"What is the main idea?","o":["Small acts of kindness help in scary times","Storms are dangerous","Cats like stairs"],"a":0}]},"story2":{"title":"The Kindness Experiment","text":"Ms. Park gave her class an assignment: do one act of kindness a day for a week and record the reaction. The excitement was high on Monday. By Wednesday, students noticed something. Kindness spread. A held door led to a shared pencil, which led to an invitation to lunch. On Friday the class wrote their conclusion: the movement of kindness is faster than the movement of gossip.","questions":[{"q":"What was the assignment?","o":["One act of kindness a day","A science quiz","A book report"],"a":0},{"q":"What did students notice?","o":["Kindness spread","Nothing changed","It was boring"],"a":0},{"q":"What was the conclusion?","o":["Kindness moves faster than gossip","Gossip is fun","Mondays are hard"],"a":0},{"q":"Which suffix is in kindness?","o":["-ness","-ment","-tion"],"a":0}]}},
  {"n":8,"name":"Words with -ous and -ive","skill":"Adjective endings","speed":0.9,"words":[["dangerous","A dangerous road."],["famous","A famous singer."],["nervous","A nervous laugh."],["curious","A curious mind."],["generous","A generous gift."],["active","An active puppy."],["creative","A creative idea."],["massive","A massive wave."],["expensive","An expensive watch."],["attentive","An attentive student."],["courageous","The courageous dog saved the cat."],["mysterious","A mysterious noise came from the attic."],["enormous","An enormous whale surfaced."],["joyous","A joyous parade."],["cautious","Be cautious on the ice."],["supportive","A supportive friend listens."],["protective","A protective mother hen."],["inventive","An inventive solution."],["decisive","A decisive leader."],["sensitive","Sensitive skin burns easily."]],"story":{"title":"The Generous Inventor","text":"Everyone in town knew Ms. Okafor as the creative inventor on Maple Street. Her workshop was massive and a little dangerous, full of spinning gears. Kids were curious but nervous about knocking on her door. One active boy named Dev finally did. She was so generous with her time that she taught him to build a wind turbine for the school roof. It was not expensive, just old bike parts. Dev was an attentive student, and by June the turbine was powering the classroom lights. Ms. Okafor became famous, but she said Dev deserved the credit.","questions":[{"q":"Why were kids nervous about Ms. Okafor?","o":["Her workshop looked dangerous","She was mean","She was famous"],"a":0},{"q":"What did Dev build?","o":["A wind turbine","A robot","A bike"],"a":0},{"q":"What does 'generous with her time' mean?","o":["She gave a lot of time to help","She charged money","She was always late"],"a":0},{"q":"Who did Ms. Okafor say deserved the credit?","o":["Dev","Herself","The school"],"a":0}]},"story2":{"title":"The Cautious Inventor","text":"Everyone knew Tomas as creative but cautious. He tested each invention a dozen times before he showed anyone. His most famous idea was an attentive alarm clock that watched you until you were truly out of bed. It was massive, nervous-making, and famous on the school news. When a curious reporter asked why he was so careful, Tomas said an inventor who is generous with time is generous with safety.","questions":[{"q":"How did people describe Tomas?","o":["Creative but cautious","Loud and fast","Lazy"],"a":0},{"q":"What did his alarm clock do?","o":["Watched you until you were out of bed","Sang","Made toast"],"a":0},{"q":"What does cautious mean?","o":["Careful","Famous","Curious"],"a":0},{"q":"Which suffix is in creative?","o":["-ive","-ous","-ful"],"a":0}]}},
  {"n":9,"name":"Words with -ly and -ful","skill":"Adverbs and more adjectives","speed":0.8,"words":[["carefully","Carry it carefully."],["suddenly","Suddenly it rained."],["quietly","Walk quietly."],["eagerly","She eagerly waited."],["honestly","Honestly, I forgot."],["thoughtful","A thoughtful note."],["powerful","A powerful engine."],["graceful","A graceful dancer."],["skillful","A skillful carpenter."],["peaceful","A peaceful lake."],["gently","Hold the kitten gently."],["bravely","She bravely spoke up."],["rarely","We rarely see snow here."],["loudly","The crowd cheered loudly."],["patiently","Wait patiently in line."],["cheerful","A cheerful greeting."],["playful","A playful puppy."],["harmful","Smoke is harmful."],["doubtful","A doubtful look."],["respectful","A respectful tone."]],"story":{"title":"The Peaceful Lake","text":"We paddled quietly across the peaceful lake at dawn. Mom steered carefully around the rocks while I eagerly watched for herons. Suddenly, a powerful splash broke the silence. A graceful fish leaped and fell back. Honestly, I almost dropped my paddle. Later, Mom, who is a skillful cook, grilled the fish we caught. She left a thoughtful note in my lunchbox the next day: Remember the lake when things get loud.","questions":[{"q":"When did they paddle?","o":["At dawn","At noon","At night"],"a":0},{"q":"What broke the silence?","o":["A fish leaping","A boat horn","Thunder"],"a":0},{"q":"What does the adverb 'eagerly' tell you?","o":["The narrator was excited to watch","The narrator was bored","The narrator was asleep"],"a":0},{"q":"What did the note tell the narrator to remember?","o":["The lake when things get loud","To bring a paddle","To eat lunch"],"a":0}]},"story2":{"title":"Quietly, the Heron","text":"The heron stood thoughtfully at the edge of the marsh, so still it looked carved. Suddenly a fish flashed. Gracefully the heron bent, and skillfully it struck. Eagerly it swallowed. Then, powerfully, it rose, wings beating slowly, and the marsh was peaceful again. Nia, who had been watching honestly without breathing, finally exhaled.","questions":[{"q":"How did the heron stand?","o":["Thoughtfully and still","Loudly","Quickly"],"a":0},{"q":"Which adverb describes how it struck?","o":["Skillfully","Peaceful","Powerful"],"a":0},{"q":"Which word is an adjective, not an adverb?","o":["Peaceful","Gracefully","Eagerly"],"a":0},{"q":"What did Nia do at the end?","o":["Exhaled","Clapped","Ran"],"a":0}]}},
  {"n":11,"name":"Greek and Latin roots","skill":"Roots tell what words mean","speed":1,"words":[["telephone","Answer the telephone."],["microscope","Look through the microscope."],["autograph","She signed an autograph."],["biology","We study biology."],["transport","Trucks transport goods."],["predict","Predict the ending."],["geography","Geography is about Earth."],["audience","The audience clapped."],["visible","The moon is visible."],["century","A century is 100 years."],["telescope","A telescope sees far."],["microphone","Speak into the microphone."],["autobiography","An autobiography is written by the person."],["biography","A biography of a president."],["portable","A portable speaker."],["dictate","Dictate the letter."],["geology","Geology studies rocks."],["audio","Turn up the audio."],["vision","Good vision helps you read."],["centipede","A centipede has many legs."]],"story":{"title":"The Science Fair Microscope","text":"For the science fair, Priya borrowed a microscope from the biology lab. She predicted that pond water would be boring. She was wrong. Under the lens, tiny creatures were visible, spinning and darting like a crowded city. On the day of the fair, the audience leaned in to look. A reporter even asked for her autograph as a joke. Priya thought about how a telephone carries sound far away and a microscope carries sight into a tiny world. Both tools, she wrote in her report, transport us somewhere we could not go alone.","questions":[{"q":"What did Priya predict about pond water?","o":["That it would be boring","That it would be full of life","That it would be green"],"a":0},{"q":"What did she see under the microscope?","o":["Tiny creatures moving","Nothing","Rocks"],"a":0},{"q":"The root 'micro' in microscope means","o":["Small","Far","Sound"],"a":0},{"q":"What did Priya say both tools do?","o":["Transport us to places we could not go alone","Make things bigger","Cost a lot"],"a":0}]},"story2":{"title":"Roots in the Garden","text":"Grandpa Theo planted words in the garden the way he planted beans. Tele means far, he said, pointing at his telescope. Phone means sound, he said, tapping his telephone. Graph means write. Micro means small. By the end of the afternoon, Lila could explain why a microscope and a telescope were cousins. Words have roots, Grandpa said, just like the beans.","questions":[{"q":"What does tele mean?","o":["Far","Sound","Small"],"a":0},{"q":"What does graph mean?","o":["Write","See","Big"],"a":0},{"q":"Why are microscope and telescope cousins?","o":["They share the root scope","They are both blue","They were bought together"],"a":0},{"q":"What does Grandpa compare word roots to?","o":["Beans","Rocks","Birds"],"a":0}]}},
  {"n":14,"name":"Homographs","skill":"Same spelling, different meanings","speed":1,"words":[["bat","A bat flew, and I swung the bat."],["bark","The dog's bark and the tree's bark."],["wave","Wave your hand at the wave."],["ring","Ring the bell, wear the ring."],["light","A light box in bright light."],["watch","Watch the clock on your watch."],["fair","A fair deal at the county fair."],["left","Turn left after you left."],["rose","The rose rose in the sun."],["bank","A bank by the river bank."],["tear","A tear in the paper. A tear on her cheek."],["lead","Lead the way. The pipe is made of lead."],["wind","The wind blew. Wind the clock."],["bow","Take a bow. Tie a bow."],["close","Close the door. Stand close."],["desert","A dry desert. Do not desert your team."],["minute","Wait a minute. A minute speck of dust."],["object","A shiny object. I object!"],["present","A present for you. Present your work."],["record","Record the song. A world record."],["produce","Farms produce food. Fresh produce."]],"story":{"title":"The Fair by the River Bank","text":"On the first day of the county fair, we parked by the river bank. A bat swooped under the lights, and my brother swung an imaginary bat at it. We watched a juggler, and I checked my watch to make sure we would not miss the fireworks. A light breeze lifted the ribbons on the rides. When the show began, a wave of color rose over the water, and every person on the bank raised a hand to wave back. It was only fair, my brother said, that the best show was free.","questions":[{"q":"Where did they park?","o":["By the river bank","At a money bank","In a field"],"a":0},{"q":"In 'a light breeze', light means","o":["Gentle, not heavy","Bright","A lamp"],"a":0},{"q":"What did people do when the fireworks rose?","o":["Waved back","Went home","Covered their eyes"],"a":0},{"q":"Why did the brother say the show was 'fair'?","o":["The best part was free","It was at the fair","It was light outside"],"a":0}]},"story2":{"title":"The Record Record","text":"Ms. Ortiz told the class she had a record. Everyone thought she meant a prize. Then she pulled out a flat black disc and played music on it. A record, she said, is also something you record on. She then asked them to record how long they could read without stopping. By the end of class, Jamal held the class record for reading, and they all understood why one word could wear two hats.","questions":[{"q":"What did the students think record meant at first?","o":["A prize","A disc","A song"],"a":0},{"q":"What was the black disc?","o":["A record for playing music","A plate","A frisbee"],"a":0},{"q":"Who set the class reading record?","o":["Jamal","Ms. Ortiz","Nobody"],"a":0},{"q":"A word with two meanings is called a","o":["Homograph","Simile","Prefix"],"a":0}]}},
  {"n":17,"name":"Shades of meaning","skill":"Pick the exact word","speed":0.8,"words":[["walk","We walk to school."],["stroll","A slow stroll in the park."],["march","Soldiers march."],["say","Say your name."],["mumble","Do not mumble."],["announce","Announce the winner."],["look","Look here."],["glance","A quick glance."],["stare","Do not stare."],["examine","Examine the clue."],["giggle","A quiet giggle."],["chuckle","A low chuckle."],["roar","A roar of laughter."],["sip","Sip the hot tea."],["gulp","Gulp the cold water."],["slurp","Do not slurp soup."],["tap","Tap on the window."],["knock","Knock on the door."],["pound","Pound on the drum."],["peek","Peek through the keyhole."]],"story":{"title":"The Parade","text":"On parade day, the band did not just walk down Main Street, they marched, knees high, drums booming. My little cousin strolled behind them, stopping to examine every candy wrapper on the ground. When the mayor took the microphone to announce the prize for best float, he did not mumble. His voice rang out over the crowd. I glanced at my sister, then stared at the stage: our float, a paper dragon, had won. For a second nobody could say anything at all.","questions":[{"q":"What is the difference between walk and march in the story?","o":["March is strong and in step","Walk is faster","They mean the same"],"a":0},{"q":"Which word means to look very closely?","o":["Examine","Glance","Stroll"],"a":0},{"q":"How did the mayor speak?","o":["Loud and clear","Quietly","Angrily"],"a":0},{"q":"Who won best float?","o":["The narrator's family","The band","The mayor"],"a":0}]},"story2":{"title":"Three Ways to Enter a Room","text":"Mrs. Gold asked three students to enter the room and then describe how they did it. Ari said she walked in. Mrs. Gold shook her head. Try again. Ari said she strolled in, relaxed and slow. Ben said he marched in, chin up. Cora, who was late, said she dashed in. See? said Mrs. Gold. Walked tells me nothing. Strolled, marched, and dashed each tell me a whole story.","questions":[{"q":"Why did Mrs. Gold reject walked?","o":["It tells nothing about how","It was misspelled","It was too long"],"a":0},{"q":"Which word shows Cora was late?","o":["Dashed","Strolled","Marched"],"a":0},{"q":"What does strolled suggest?","o":["Relaxed and slow","Angry","Fast"],"a":0},{"q":"Words with slightly different meanings are called","o":["Shades of meaning","Prefixes","Idioms"],"a":0}]}},
  {"n":18,"name":"Context clues","skill":"Use the sentence to find meaning","speed":0.9,"words":[["reluctant","The reluctant puppy would not go in the bath."],["abundant","Apples were abundant, piled in every basket."],["fragile","The fragile vase cracked when it tipped."],["vacant","The vacant house had no one living in it."],["cautious","The cautious hiker tested each rock."],["drowsy","After lunch I felt drowsy and yawned."],["sturdy","The sturdy bridge held the heavy truck."],["famished","Famished after the race, he ate three plates."],["timid","The timid mouse hid from the light."],["ancient","The ancient coin was a thousand years old."],["brittle","The old paper was brittle and cracked."],["dense","The forest was so dense that no light came through."],["frigid","The frigid air froze our breath."],["glimpse","I caught a glimpse of the deer before it ran."],["murky","The murky water hid the bottom of the pond."],["parched","After the hike, we were parched and drank a whole bottle."],["scurry","Mice scurry quickly across the floor."],["tattered","The tattered flag was torn and faded."],["vast","The vast desert stretched for miles."],["weary","The weary hikers sat down at last."]],"story":{"title":"The Vacant Lighthouse","text":"The lighthouse had been vacant for years; no keeper lived there anymore. Jun was reluctant to go inside, dragging her feet at the door. Her brother was more cautious than scared, testing each step before putting his weight on it. The stairs were sturdy, though, built from thick oak that held them easily. At the top they found an ancient logbook, its pages so fragile they turned them with two fingers. Dust was abundant, covering every surface. By sunset, drowsy and famished, they climbed down with one line copied from the book: Keep the light burning for those still at sea.","questions":[{"q":"What does 'vacant' mean, based on the clue?","o":["Empty, no one living there","Haunted","Tall"],"a":0},{"q":"Which word means careful?","o":["Cautious","Reluctant","Drowsy"],"a":0},{"q":"How could you tell the logbook was fragile?","o":["They turned pages with two fingers","It was heavy","It was new"],"a":0},{"q":"What did the line from the book ask the keeper to do?","o":["Keep the light burning for sailors","Lock the door","Sweep the dust"],"a":0}]},"story2":{"title":"The Parched Garden","text":"By August the garden was parched. The soil was brittle and cracked, and the once dense tomato vines hung tattered and weary. Zoe refused to give up. She glimpsed a way: a barrel under the gutter to catch the rain that came in the frigid early mornings. The first storm filled it. By September, the vines were dense again, and Zoe's bucket made the trip from barrel to garden every single day.","questions":[{"q":"What does parched mean in the story?","o":["Very dry","Flooded","Cold"],"a":0},{"q":"What clue shows the meaning of brittle?","o":["Cracked","Dense","Weary"],"a":0},{"q":"What was Zoe's solution?","o":["A rain barrel under the gutter","Buying water","Giving up"],"a":0},{"q":"What does dense mean here?","o":["Thick and full","Thin","Tall"],"a":0}]}},
  {"n":20,"name":"Similes and metaphors","skill":"Comparing one thing to another","speed":0.9,"words":[["simile","A simile uses like or as."],["metaphor","A metaphor says it is."],["compare","Compare two things."],["describe","Describe the scene."],["image","Paint an image with words."],["gentle","As gentle as a lamb."],["swift","Swift as the wind."],["glitter","Stars glitter."],["thunder","His voice was thunder."],["blanket","A blanket of snow."],["roar","The engine let out a roar like a lion."],["feather","The snow fell as light as a feather."],["ocean","Her mind was an ocean of ideas."],["statue","He stood as still as a statue."],["sparkle","Her eyes sparkle like stars."],["rocket","He is a rocket on the track."],["whisper","The breeze was a whisper."],["mountain","The homework was a mountain."],["cheetah","She runs like a cheetah."],["volcano","His temper was a volcano."]],"story":{"title":"Snow Like a Blanket","text":"When I woke, a blanket of snow had covered the town. The street was a white river. My dog ran out as swift as the wind and came back with a nose like a cold pebble. Grandpa's laugh was thunder from the porch. Later, the sun turned the yard into a field of glitter. I tried to describe it all in my journal. Some things I compared with like or as. Others I simply called what they were: the pine tree was a tall green soldier, standing guard until spring.","questions":[{"q":"Which is a metaphor from the story?","o":["The street was a white river","As swift as the wind","A nose like a cold pebble"],"a":0},{"q":"Which is a simile?","o":["As swift as the wind","Grandpa's laugh was thunder","The pine tree was a soldier"],"a":0},{"q":"What does 'a field of glitter' describe?","o":["Sunlight shining on snow","A party","A gold mine"],"a":0},{"q":"What was the pine tree compared to?","o":["A soldier standing guard","A blanket","A river"],"a":0}]},"story2":{"title":"The Gym Was a Beehive","text":"On tournament day the gym was a beehive, buzzing with players and parents. Coach Reyes spoke like thunder over the noise. Nora's legs felt like jelly before the first serve. Then the ball floated over the net as slow as a feather, and she smashed it. After that she was a rocket. By the final game, the beehive was chanting her name.","questions":[{"q":"What is the gym compared to?","o":["A beehive","A library","A pool"],"a":0},{"q":"Which is a simile?","o":["As slow as a feather","The gym was a beehive","She was a rocket"],"a":0},{"q":"How did Nora feel at first?","o":["Nervous, legs like jelly","Bored","Angry"],"a":0},{"q":"Which is a metaphor?","o":["She was a rocket","As slow as a feather","Like thunder"],"a":0}]}},
  {"n":21,"name":"Idioms","skill":"Sayings that do not mean what they say","speed":0.9,"words":[["idiom","An idiom is a saying."],["literal","The literal meaning."],["expression","A common expression."],["raining cats and dogs","It is raining cats and dogs."],["piece of cake","The test was a piece of cake."],["break the ice","A joke can break the ice."],["hit the hay","Time to hit the hay."],["spill the beans","Do not spill the beans."],["under the weather","I feel under the weather."],["cost an arm and a leg","That bike cost an arm and a leg."],["on cloud nine","After the win, she was on cloud nine."],["all ears","Tell me, I am all ears."],["once in a blue moon","We eat out once in a blue moon."],["hold your horses","Hold your horses, we are not ready."],["in a nutshell","In a nutshell, we won."],["let the cat out of the bag","He let the cat out of the bag about the party."],["a blessing in disguise","The rain was a blessing in disguise."],["bite the bullet","Bite the bullet and go to the dentist."],["the ball is in your court","Now the ball is in your court."],["call it a day","Let's call it a day."]],"story":{"title":"Grandma's Sayings","text":"My cousin Luis came from Mexico to visit, and Grandma's sayings confused him. When she said it was raining cats and dogs, he looked outside for puppies. When she said the pie was a piece of cake, he asked which one it was. I explained that idioms are expressions whose literal words do not match their meaning. To break the ice, I taught him three a day. By Friday, when Grandma said it was time to hit the hay, Luis grinned and said, I am under the weather, so I will spill the beans: I love it here.","questions":[{"q":"Why was Luis confused?","o":["He took idioms literally","He did not like pie","It was raining"],"a":0},{"q":"What does 'hit the hay' mean?","o":["Go to bed","Feed the horses","Hit something"],"a":0},{"q":"What does 'break the ice' mean here?","o":["Make someone feel comfortable","Crack frozen water","Start a fight"],"a":0},{"q":"How did Luis feel at the end?","o":["He loved his visit","He wanted to go home","He was sick"],"a":0}]},"story2":{"title":"Dad Means It Literally","text":"Dad came home and said he was so hungry he could eat a horse. My little brother burst into tears and hid the toy horse. Then Dad said we should hit the road, and my brother went looking for a hammer. Finally Dad said, I'm all ears, and my brother stared at Dad's head to check. We explained that idioms are not literal. My brother said that was a piece of cake, and then asked where the cake was.","questions":[{"q":"Why did the brother cry?","o":["He thought Dad would eat the toy horse","He was hungry","He lost a game"],"a":0},{"q":"What does hit the road mean?","o":["Leave","Hammer the street","Fall down"],"a":0},{"q":"What is an idiom?","o":["A phrase that is not meant literally","A loud word","A kind of cake"],"a":0},{"q":"What does piece of cake mean?","o":["Easy","Dessert","Small"],"a":0}]}},
  {"n":24,"name":"Academic vocabulary 1","skill":"Words for thinking and school","speed":0.9,"words":[["analyze","Analyze the chart."],["evidence","Find the evidence."],["summarize","Summarize the chapter."],["conclude","What can you conclude?"],["sequence","Put events in sequence."],["compare","Compare the two stories."],["contrast","Contrast day and night."],["infer","Infer how she feels."],["identify","Identify the main idea."],["explain","Explain your answer."],["describe","Describe the setting."],["predict","Predict the ending."],["support","Support your answer with evidence."],["organize","Organize your notes."],["define","Define the word."],["classify","Classify the animals."],["illustrate","Illustrate your point with an example."],["interpret","Interpret the graph."],["revise","Revise your draft."],["demonstrate","Demonstrate how it works."]],"story":{"title":"The Case of the Missing Lunch","text":"When Marcus's lunch vanished from the classroom fridge, our teacher turned it into a mystery lesson. First, we had to identify the facts: the lunch was there at nine and gone by eleven. Then we gathered evidence: crumbs by the window and a muddy paw print on the sill. We put the clues in sequence and compared them with what we knew about the school cat. We could infer that the cat had climbed in through the open window. Finally, we had to explain our conclusion in writing. Marcus got a new sandwich, and the cat got a lecture.","questions":[{"q":"What was the mystery?","o":["A missing lunch","A lost cat","A broken window"],"a":0},{"q":"Which clue was evidence?","o":["A muddy paw print","The time of lunch","The teacher's name"],"a":0},{"q":"What did the class infer?","o":["The cat climbed in through the window","A student took it","Marcus forgot his lunch"],"a":0},{"q":"What does 'sequence' mean in the story?","o":["Order of events","A kind of cat","A sandwich"],"a":0}]},"story2":{"title":"The Evidence Jar","text":"Mr. Adeyemi kept a jar labeled Evidence on his desk. Whenever a student made a claim, he pointed to it. Ravi said the class hamster was the smartest animal alive. Prove it, said Mr. Adeyemi. So Ravi set up a maze, timed the hamster three days in a row, and compared the results to a video of a mouse. His conclusion was careful: the hamster was fast, but smartest alive was too big a claim. The class voted to put a cheese cube in the jar for the hamster anyway.","questions":[{"q":"What was the jar for?","o":["Evidence for claims","Snacks","Lost pencils"],"a":0},{"q":"How did Ravi test his claim?","o":["A maze, timed three days","He asked his mom","He guessed"],"a":0},{"q":"What was his conclusion?","o":["The hamster was fast but smartest alive was too big a claim","The hamster was the smartest animal","The mouse was smarter"],"a":0},{"q":"Which word means to reach a decision from evidence?","o":["Conclude","Describe","Organize"],"a":0}]}},
  {"n":25,"name":"Academic vocabulary 2","skill":"Words from science and social studies","speed":0.9,"words":[["observe","Observe the beetle."],["hypothesis","Test your hypothesis."],["experiment","Run an experiment."],["environment","Protect the environment."],["resource","Water is a resource."],["culture","Learn about a culture."],["government","The government makes laws."],["citizen","A good citizen votes."],["tradition","A family tradition."],["region","A dry region."],["community","Our community cleaned the park."],["economy","The economy is about money and jobs."],["landmark","The old clock tower is a landmark."],["ancestor","My ancestor came from Ghana."],["climate","A desert climate is dry."],["migration","Bird migration happens in fall."],["population","The city's population is one million."],["conservation","Conservation protects forests."],["agriculture","Agriculture means farming."],["technology","New technology changes work."]],"story":{"title":"Rain Barrels for the Region","text":"Our region had a dry summer, and the town asked citizens for ideas to save water, an important resource. My class formed a hypothesis: if houses collected rain in barrels, gardens would need less tap water. We ran an experiment on the school garden, observing two beds for a month. The bed watered from the barrel grew just as well. We presented our data to the town government. They started a tradition: every spring, the town gives away rain barrels, and kids paint them with pictures of local culture and wildlife to protect the environment.","questions":[{"q":"What problem did the region have?","o":["A dry summer","Too much rain","No gardens"],"a":0},{"q":"What was the hypothesis?","o":["Rain barrels would reduce tap water use","Gardens need no water","Paint helps plants"],"a":0},{"q":"Who did the class present to?","o":["The town government","Their parents","A TV station"],"a":0},{"q":"What new tradition began?","o":["Giving away painted rain barrels each spring","A water festival","A school holiday"],"a":0}]},"story2":{"title":"A Map of the Region","text":"For the social studies fair, Hana's group made a map of their region. They marked every resource: the river, the quarry, the farms, the wind turbines on the ridge. Then they interviewed a farmer and a factory worker about their traditions. Their hypothesis was that the river explained everything, where people settled, what they grew, and where the roads went. The judges agreed, and so did the farmer, who said his great-grandfather had chosen the land for exactly that reason.","questions":[{"q":"What did the group mark on the map?","o":["Resources","Schools","Restaurants"],"a":0},{"q":"What was their hypothesis?","o":["The river explained where people settled","Wind made the roads","Farms came first"],"a":0},{"q":"Who did they interview?","o":["A farmer and a factory worker","The mayor","A judge"],"a":0},{"q":"What does a region mean?","o":["An area of land with shared features","A kind of map","A river"],"a":0}]}},
  {"n":33,"name":"Words about character","skill":"Describe people in stories","speed":0.8,"words":[["honest","An honest friend."],["loyal","A loyal dog."],["stubborn","A stubborn goat."],["humble","A humble champion."],["ambitious","An ambitious plan."],["cheerful","A cheerful helper."],["selfish","A selfish choice."],["courageous","A courageous rescue."],["patient","A patient teacher."],["witty","A witty remark."],["generous","A generous host shares everything."],["curious","A curious cat explores."],["timid","A timid mouse hides."],["bold","A bold explorer climbs first."],["greedy","The greedy dragon kept all the gold."],["gentle","A gentle giant."],["clever","A clever fox."],["reckless","A reckless driver speeds."],["sincere","A sincere apology."],["mischievous","A mischievous monkey steals hats."]],"story":{"title":"The Stubborn Goat and the Patient Girl","text":"Billy was the most stubborn goat on the farm. He would not cross the stream, not for carrots and not for anyone. Amira was patient. Every day she sat by the water and talked to him. Her brother called it a selfish waste of time, since she could have been playing. But Amira was loyal to the goat. On the tenth day, she walked across the stream without looking back, and Billy, not wanting to be alone, followed. She never bragged about it. Honest and humble, she just said the goat decided on his own.","questions":[{"q":"Which word best describes Billy?","o":["Stubborn","Cheerful","Witty"],"a":0},{"q":"Which word best describes Amira?","o":["Patient","Selfish","Ambitious"],"a":0},{"q":"How did Amira finally get Billy to cross?","o":["She walked across without looking back","She carried him","She used carrots"],"a":0},{"q":"Why is Amira called humble?","o":["She gave the goat the credit","She was quiet","She was small"],"a":0}]},"story2":{"title":"The Loyal Crow and the Witty Fox","text":"A loyal crow visited the same farmer every morning for a crust. A witty fox wanted the crust. Dear crow, said the fox, I hear your voice is the finest in the valley. The crow, who was humble and not stubborn, simply said, thank you, and ate the crust first. Then it sang. The fox, outsmarted, went hungry but admitted the song was good. Flattery, the crow said, tastes better after breakfast.","questions":[{"q":"Which word describes the crow's visits to the farmer?","o":["Loyal","Greedy","Reckless"],"a":0},{"q":"What did the fox want?","o":["The crust","A song","A friend"],"a":0},{"q":"Why did the fox's trick fail?","o":["The crow ate first, then sang","The crow flew away","The farmer came"],"a":0},{"q":"What does witty mean?","o":["Clever and funny","Lazy","Angry"],"a":0}]}},
  {"n":35,"name":"Transition words","skill":"Words that connect ideas","speed":0.8,"words":[["however","It rained; however, we played."],["therefore","I studied; therefore, I passed."],["meanwhile","Meanwhile, the soup cooked."],["although","Although tired, she ran."],["finally","Finally, we arrived."],["besides","Besides, it is fun."],["otherwise","Hurry; otherwise, we are late."],["instead","Walk instead of ride."],["similarly","Similarly, cats nap."],["consequently","Consequently, the plant died."],["first","First, mix the flour."],["next","Next, add the eggs."],["then","Then stir."],["afterward","Afterward, we rested."],["in addition","In addition, bring water."],["for example","For example, a bear hibernates."],["as a result","As a result, the plant grew."],["on the other hand","On the other hand, it was cheap."],["in conclusion","In conclusion, recycling helps."],["because of","Because of the rain, we stayed inside."]],"story":{"title":"The Science of Pancakes","text":"Dad wanted to make pancakes from scratch; however, we were out of eggs. Instead of giving up, he looked online and found that mashed banana works similarly to an egg. Meanwhile, I heated the pan. Although the first pancake stuck, the second one flipped perfectly. Besides, burnt edges taste fine with syrup. We had forgotten the baking powder; consequently, the pancakes were flat. Therefore, Dad called them crepes. Finally, we ate them all, and nobody complained. Otherwise, there would have been no breakfast at all.","questions":[{"q":"What were they missing at the start?","o":["Eggs","Flour","Syrup"],"a":0},{"q":"What did Dad use instead of eggs?","o":["Mashed banana","Milk","Butter"],"a":0},{"q":"Why were the pancakes flat?","o":["They forgot baking powder","The pan was cold","They used too much milk"],"a":0},{"q":"Which word signals a result?","o":["Consequently","Meanwhile","Although"],"a":0}]},"story2":{"title":"How We Lost and Found the Cat","text":"First, the cat vanished. Meanwhile, Dad searched the garage; however, he found only a sock. Therefore, we made posters. Although the posters were everywhere, nobody called. Finally, on the third day, we heard a faint meow from the neighbor's shed. Consequently, the neighbor got a plate of cookies, and the cat got a collar with a bell. Otherwise, we agreed, this would happen again.","questions":[{"q":"Which word shows two things happened at the same time?","o":["Meanwhile","Finally","Therefore"],"a":0},{"q":"Where was the cat?","o":["The neighbor's shed","The garage","A tree"],"a":0},{"q":"Which word signals a result?","o":["Consequently","Although","Meanwhile"],"a":0},{"q":"Why did the cat get a bell?","o":["So it would not get lost again","As a prize","For music"],"a":0}]}},
  {"n":36,"name":"Point of view","skill":"Who is telling the story","speed":0.8,"words":[["narrator","The narrator tells the story."],["first person","First person uses I."],["third person","Third person uses he or she."],["opinion","That is my opinion."],["fact","A fact is true."],["perspective","See it from her perspective."],["character","The main character."],["dialogue","Dialogue is talking."],["plot","The plot of the story."],["theme","The theme is friendship."],["protagonist","The protagonist is the main character."],["antagonist","The antagonist works against the hero."],["second person","Second person uses you."],["omniscient","An omniscient narrator knows all thoughts."],["bias","Bias means favoring one side."],["evidence","Give evidence for your opinion."],["viewpoint","Explain your viewpoint."],["setting","The setting is a castle."],["mood","The mood is spooky."],["audience","Know your audience."]],"story":{"title":"Two Sides of the Fence","text":"From my perspective, the new neighbor's dog was a menace. It barked every morning and dug under our fence. That is my opinion, and I had plenty of facts to back it up. Then I met the neighbor, Mr. Ruiz, and heard his side. The dog, Pepper, had been a rescue, scared of being alone. Every bark was a cry for company. We agreed to a plan: I would walk Pepper after school. Now the only thing that digs under the fence is my hand, reaching through to scratch Pepper's ears. The theme of this story, if you asked me, is that there are two sides to every fence.","questions":[{"q":"Who is telling the story?","o":["A kid who lives next to the dog","Mr. Ruiz","Pepper"],"a":0},{"q":"Which point of view is it?","o":["First person","Third person","Second person"],"a":0},{"q":"Why did Pepper bark?","o":["She was scared of being alone","She was angry","She was hungry"],"a":0},{"q":"What is the theme?","o":["There are two sides to every story","Dogs are bad","Fences are strong"],"a":0}]},"story2":{"title":"The Broken Window, Told Twice","text":"I was practicing my pitch when the ball slipped, Theo wrote. I did not mean to break the window. That is first person: we hear only Theo's side. The narrator of the second version wrote, Theo had been warned twice not to pitch near the house. That is third person, with a different perspective. The class read both. Which is true? asked Ms. Vu. Both, said Mila, but neither is the whole story.","questions":[{"q":"Which version uses first person?","o":["Theo's own account","The narrator's account","Neither"],"a":0},{"q":"What does the third-person version add?","o":["Theo had been warned twice","The window was open","Theo was a hero"],"a":0},{"q":"What did Mila conclude?","o":["Both are true but not the whole story","Theo lied","The narrator lied"],"a":0},{"q":"A character's way of seeing events is their","o":["Perspective","Plot","Dialogue"],"a":0}]}},
  {"n":37,"name":"Cause and effect","skill":"Why things happen","speed":0.8,"words":[["cause","The cause of the flood."],["effect","The effect of rain."],["because","Because it snowed."],["result","As a result."],["reason","The reason why."],["impact","A big impact."],["trigger","What triggered it?"],["outcome","A good outcome."],["influence","Her influence on me."],["lead","That can lead to trouble."],["therefore","It rained, therefore we stayed in."],["since","Since it was late, we left."],["so","I was tired, so I slept."],["consequence","A consequence of the storm was flooding."],["source","Find the source of the leak."],["chain reaction","One fall caused a chain reaction."],["spark","A spark started the fire."],["ripple","A ripple effect across the pond."],["benefit","A benefit of exercise is energy."],["prevent","Helmets prevent injuries."]],"story":{"title":"The Night the River Rose","text":"Three days of rain caused the river to rise above its banks. As a result, the road to the school flooded. Because the buses could not run, the mayor closed school for a day. The outcome was not all bad: families filled sandbags together, and the effort had a lasting impact. Neighbors who had never spoken shared coffee and shovels. The flood was the trigger, but the real reason the town grew closer was that people chose to help. One wet night influenced the whole year.","questions":[{"q":"What caused the river to rise?","o":["Three days of rain","A broken dam","Melting snow"],"a":0},{"q":"What was the effect on school?","o":["It closed for a day","It stayed open","It moved"],"a":0},{"q":"What was a positive outcome?","o":["Neighbors grew closer","The road was rebuilt","Buses got new tires"],"a":0},{"q":"What does 'trigger' mean here?","o":["The event that started it","A part of a gun","A storm"],"a":0}]},"story2":{"title":"Why the Bread Did Not Rise","text":"Omar's bread came out flat as a plate. He traced the cause backward. The dough had not risen because the yeast was dead. The yeast was dead because the water had been too hot. The water was too hot because he had boiled it, not warmed it. One small cause, three effects, and a very flat loaf. The next day he used a thermometer. The result was a loaf as tall as a hat, and a lesson about chains of cause and effect.","questions":[{"q":"What was the first cause?","o":["Boiling the water","Old flour","A cold oven"],"a":0},{"q":"What was the effect of hot water?","o":["The yeast died","The bread burned","The dough rose"],"a":0},{"q":"What did Omar change the next day?","o":["He used a thermometer","He bought bread","He skipped yeast"],"a":0},{"q":"A series of linked causes and effects is a","o":["Chain","Simile","Setting"],"a":0}]}},
  {"n":40,"name":"Nonfiction words","skill":"Reading information texts","speed":0.8,"words":[["heading","Read the heading first."],["caption","The caption explains the photo."],["diagram","A diagram of the heart."],["glossary","Check the glossary."],["index","Use the index."],["paragraph","A short paragraph."],["topic","The topic sentence."],["source","Name your source."],["chart","Read the chart."],["label","The label on the map."],["table of contents","The table of contents lists chapters."],["subheading","A subheading divides a section."],["bold print","Key words are in bold print."],["timeline","A timeline shows dates in order."],["map","A map shows places."],["sidebar","A sidebar adds a fun fact."],["bullet","A bullet marks a list item."],["footnote","A footnote gives a source."],["summary","A summary is short."],["fact","A fact can be checked."]],"story":{"title":"How to Read a Science Book","text":"A science book is not read like a story. Start with the headings; they tell you the topic of each section. Look at the diagrams and read the captions, because pictures often explain more than paragraphs. If a word is new, the glossary at the back defines it. The index lists every page where a topic appears, so you can jump straight to volcanoes without reading about rocks first. Charts give numbers at a glance, and labels on a map tell you what you are looking at. Finally, check the source. A good book tells you where its facts came from.","questions":[{"q":"What do headings tell you?","o":["The topic of a section","The author's name","The price"],"a":0},{"q":"Where would you look up a new word?","o":["The glossary","The index","A chart"],"a":0},{"q":"What does the index help you do?","o":["Find every page about a topic","Define words","Read captions"],"a":0},{"q":"Why check the source?","o":["To know where the facts came from","To find the price","To see the pictures"],"a":0}]},"story2":{"title":"Finding the Hummingbird","text":"Jun had to find out how fast a hummingbird's wings beat. He did not read the whole book. First he checked the index for hummingbird and found page 44. The heading there said Birds of the Americas. A diagram showed wing motion, and the caption gave the number: up to eighty beats per second. A sidebar in a box added that their hearts beat over a thousand times a minute. The glossary explained the word hover. Four tools, two minutes, done.","questions":[{"q":"Which feature did Jun use first?","o":["The index","The glossary","The cover"],"a":0},{"q":"Where was the number of wing beats?","o":["In a caption","In the title","In the index"],"a":0},{"q":"What did the sidebar add?","o":["A fact about heart rate","A joke","A map"],"a":0},{"q":"What does a glossary do?","o":["Explains words","Lists pages","Shows pictures"],"a":0}]}},
  {"n":42,"name":"Persuasive words","skill":"Words that try to convince","speed":0.7,"words":[["convince","Convince me."],["argument","A strong argument."],["persuade","Persuade the class."],["reason","Give a reason."],["support","Support your claim."],["claim","Make a claim."],["evidence","Show evidence."],["opinion","In my opinion."],["benefit","A clear benefit."],["recommend","I recommend it."],["appeal","An appeal to emotion."],["audience","Know your audience."],["counter","Counter the other side."],["effective","An effective speech convinces."],["emphasize","Emphasize your main point."],["expert","Quote an expert."],["statistic","A statistic is a number fact."],["urge","I urge you to vote."],["solution","Offer a solution."],["call to action","End with a call to action."]],"story":{"title":"Why Our School Needs a Garden","text":"I claim that our school should build a garden, and I have three reasons. First, students who grow food are more likely to eat vegetables; that is evidence from a study my teacher showed us. Second, a garden gives science class a real laboratory where we can measure, observe, and record. Third, the benefit goes beyond students: extra vegetables could go to the food bank. Some people argue that a garden costs money. I would persuade them with this: seeds cost less than a single textbook, and the lessons last longer. I recommend we start with one raised bed this spring.","questions":[{"q":"What is the writer's claim?","o":["The school should build a garden","Textbooks are too expensive","Vegetables taste bad"],"a":0},{"q":"Which is evidence, not opinion?","o":["A study showed students who grow food eat more vegetables","Gardens are nice","I like tomatoes"],"a":0},{"q":"What argument against the garden is mentioned?","o":["It costs money","It takes too long","Kids hate dirt"],"a":0},{"q":"What does the writer recommend?","o":["Start with one raised bed","Build ten beds","Buy a greenhouse"],"a":0}]},"story2":{"title":"A Letter About Lunch","text":"Dear Principal Diaz, I am writing to persuade you to add five minutes to lunch. My first reason is health: our nurse says students who eat too fast get stomachaches. My second reason is evidence from Room 9, where a longer lunch last spring led to fewer afternoon arguments. Some may claim we would lose class time. However, five calm minutes would benefit every lesson that follows. I recommend a two-week trial. Sincerely, Priya.","questions":[{"q":"What is Priya's claim?","o":["Lunch should be five minutes longer","Lunch should be shorter","School should end early"],"a":0},{"q":"What evidence does she give?","o":["The nurse and Room 9's results","A movie","Her own opinion only"],"a":0},{"q":"What is the counterclaim she addresses?","o":["Losing class time","Food cost","Noise"],"a":0},{"q":"What does she recommend?","o":["A two-week trial","A vote","A party"],"a":0}]}},
  {"n":49,"name":"Reading a longer text","skill":"Main idea, details, and inference","speed":0.7,"words":[["inference","Make an inference."],["conclusion","Draw a conclusion."],["summary","Write a summary."],["detail","A key detail."],["main idea","Find the main idea."],["paragraph","Each paragraph has a point."],["structure","The text structure."],["purpose","The author's purpose."],["tone","A cheerful tone."],["mood","A spooky mood."],["theme","The theme is friendship."],["sequence","Put events in sequence."],["context","Use context to guess the meaning."],["cite","Cite the page number."],["paraphrase","Paraphrase in your own words."],["evidence","Find evidence in the text."],["draft","Write a first draft."],["revise","Revise for clarity."],["genre","Mystery is a genre."],["chapter","Read chapter three."]],"story":{"title":"The Clockmaker's Apprentice","text":"In the mountain village of Alder, every house kept a clock made by old Mr. Brandt. When his hands began to shake, he took on an apprentice: a girl named Wren who had fixed her grandmother's radio with a hairpin.\n\nFor a year, Wren learned the names of every gear and the patience to wait while glue dried. Mr. Brandt rarely praised her. He only said, again, and she did it again. One winter night the church clock stopped, and the village woke late and confused. Mr. Brandt's hands were too unsteady to climb the tower.\n\nWren climbed alone. The wind rattled the bells. Inside the clock, she found a frozen spring and warmed it in her gloved hands until it moved. When the bell finally rang, the whole village looked up. Mr. Brandt, watching from his window, said nothing. But the next morning, the sign on the shop door had changed. It now read: Brandt and Wren, Clockmakers.","questions":[{"q":"What is the main idea?","o":["Through patience and practice, Wren earned her place as a clockmaker","Clocks are hard to fix","Villages need bells"],"a":0},{"q":"Which detail shows Mr. Brandt was a strict teacher?","o":["He only said 'again'","He climbed the tower","He changed the sign"],"a":0},{"q":"What can you infer from the new sign?","o":["Mr. Brandt now saw Wren as his equal","The shop was sold","Wren quit"],"a":0},{"q":"What was wrong with the church clock?","o":["A spring had frozen","The bell fell","A gear was missing"],"a":0},{"q":"What is the mood of the final paragraph?","o":["Proud and quiet","Scary","Silly"],"a":0}]},"story2":{"title":"The Weather Station on the Roof","text":"When the school's old weather station broke, nobody expected fourth graders to fix it. Amara did. She found the manual in a dusty closet and read every page, taking notes on a legal pad. The structure of the manual helped: a diagram, then steps, then a troubleshooting table. The wind vane was stuck with rust. The rain gauge had a cracked tube. The thermometer was fine but faced the sun, which made every reading too high. Amara and two friends oiled the vane, replaced the tube with a piece of clear pipe from the art room, and moved the thermometer into the shade. Then came the hard part: proving it worked. For two weeks they compared their readings with the town's official numbers. The difference was less than one degree. Their report, with a chart and a summary, hung in the hallway all spring. The main idea, Amara wrote in the last paragraph, is that broken does not mean finished.","questions":[{"q":"What was wrong with the thermometer?","o":["It faced the sun","It was cracked","It was missing"],"a":0},{"q":"How did they prove the station worked?","o":["Compared readings with official numbers for two weeks","Asked the principal","Took a photo"],"a":0},{"q":"What is the main idea of the story?","o":["Broken does not mean finished","Rust is bad","Manuals are long"],"a":0},{"q":"Which text feature helped Amara most?","o":["The manual's structure of diagram, steps, and table","The cover","The index"],"a":0},{"q":"What was the tone of the last paragraph?","o":["Proud and hopeful","Angry","Scared"],"a":0}]}}
] });
